INSERT INTO `site_settings` VALUES (1,'site_name','Site Name','general','Nirwana Tour Lampung','2026-10-26 22:57:57','2026-10-26 22:57:57'),(2,'tagline','Tagline & Subjudul SEO Beranda','general','Biro Wisata, Paket Tour & Sewa Bus Terpercaya','2026-10-26 22:57:57','2026-10-31 18:28:35'),(3,'whatsapp_number','Nomor WhatsApp Resmi (Tombol Navbar & Chat)','general','628999999999','2026-10-26 22:57:57','2026-10-31 19:43:44'),(4,'phone','Phone','general','0822-6961-6188','2026-10-26 22:57:57','2026-10-27 07:24:25'),(5,'email','Email','general','info@nirwanatour.com','2026-10-26 22:57:57','2026-10-26 22:57:57'),(6,'address','Address','general','Jl. Pangeran Antasari No. 88, Kedamaian, Kota Bandar Lampung, Lampung 35122','2026-10-26 22:57:57','2026-10-26 22:57:57'),(7,'instagram','Instagram','general','https://www.instagram.com/nirwana_tourlampung/?utm_source=ig_web_button_share_sheet','2026-10-26 22:57:57','2026-10-27 07:24:25'),(8,'tiktok','Tiktok','general','https://www.tiktok.com/@nirwana_tour_travel?is_from_webapp=1&sender_device=pc','2026-10-26 22:57:57','2026-10-27 07:24:25'),(10,'youtube','Youtube','general','https://youtube.com/@nirwanatourlampung?si=ZMFi9b5dvpn0NKfr','2026-10-26 22:57:57','2026-10-27 08:35:35'),(11,'operating_hours','Operating Hours','general','Senin - Sabtu: 08:00 - 17:00 WIB','2026-10-26 22:57:57','2026-10-26 22:57:57'),(12,'hero_title','Judul Hero','home','Selamat Datang di Website Nirwana Tour and Travel Lampung','2026-10-26 22:57:57','2026-11-03 05:55:07'),(13,'hero_subtitle','Hero Subtitle','general','Biro perjalanan wisata resmi berizin di Bandar Lampung. Kami melayani paket tour Lampung, Jawa, Bali, study tour sekolah, family gathering kantor, dan sewa bus pariwisata eksekutif.','2026-10-26 22:57:57','2026-10-26 22:57:57'),(14,'about_company','Ringkasan Profil Perusahaan','about','Nirwana Tour Lampung adalah biro perjalanan wisata berizin resmi (TDUP & NIB) yang telah berpengalaman lebih dari 8 tahun mendampingi ribuan wisatawan lokal maupun nusantara mengeksplorasi keindahan alam dan budaya Indonesia dengan pelayanan standar V.I.P yang aman, nyaman, dan berkesan.','2026-10-26 22:57:57','2026-10-29 05:39:20'),(15,'google_analytics_id','Google Analytics Id','general','','2026-10-29 03:48:02','2026-11-03 05:54:50'),(16,'meta_pixel_id','Meta Pixel Id','general','','2026-10-29 03:48:02','2026-11-03 05:54:50'),(17,'google_site_verification','Google Site Verification','general','','2026-10-29 03:48:02','2026-11-03 05:54:50'),(18,'google_maps_review_url','Tautan Google Maps Review','social_proof','https://maps.google.com/?q=Nirwana+Tour+Lampung','2026-10-29 03:48:02','2026-10-29 03:48:02'),(19,'google_maps_rating','Rating Bintang Google Maps','social_proof','4.9','2026-10-29 03:48:02','2026-10-29 03:48:02'),(20,'google_maps_reviews_count','Jumlah Ulasan Google Maps','social_proof','250+','2026-10-29 03:48:02','2026-10-29 03:48:02'),(21,'owner_name','Nama Pimpinan','about','Kiki M Alfin','2026-10-29 05:39:20','2026-11-03 05:55:05'),(22,'owner_role','Jabatan & Masa Berdiri','about','Pimpinan & Founder - Nirwana Tour Lampung • Sejak 2022','2026-10-29 05:39:20','2026-10-29 06:56:32'),(23,'owner_quote','Kutipan Sambutan Pemilik','about','Selamat datang di Nirwana Tour Lampung. Bagi kami, setiap perjalanan bukan sekadar mengantar Anda ke destinasi, melainkan sebuah amanah untuk menghadirkan rasa aman, kenyamanan prima, dan kenangan indah yang abadi bersama orang-orang tercinta.','2026-10-29 05:39:20','2026-10-29 05:39:20'),(24,'owner_photo','Foto Pemilik / Founder','about','settings/6DOr3906drwWiwa9KyQ71QGv1VMVZ5IRelfHqBDl.png','2026-10-29 05:39:20','2026-10-30 21:15:24'),(25,'about_description','Deskripsi Detail Profil Perusahaan','about','Dengan pengalaman lebih dari 8 tahun, kami telah melayani ribuan pelanggan mulai dari keluarga, sekolah, universitas, instansi pemerintahan, hingga BUMN & perusahaan swasta nasional. Setiap rencana perjalanan kami susun secara terstruktur dengan pemandu berlisensi dan armada transportasi pariwisata terawat.','2026-10-29 05:39:20','2026-10-29 05:39:20'),(26,'stat_years_count','Statistik: Tahun Pengalaman (Angka)','about','5','2026-10-29 05:39:20','2026-10-29 06:54:39'),(27,'stat_years_label','Statistik: Tahun Pengalaman (Label)','about','Tahun Pengalaman','2026-10-29 05:39:20','2026-10-29 05:39:20'),(28,'stat_trips_count','Statistik: Trip Terlaksana (Angka)','about','100+','2026-10-29 05:39:20','2026-10-29 06:54:01'),(29,'stat_trips_label','Statistik: Trip Terlaksana (Label)','about','Trip Terlaksana','2026-10-29 05:39:20','2026-10-29 05:39:20'),(30,'stat_satisfaction_count','Statistik: Kepuasan Pelanggan (Angka)','about','99','2026-10-29 05:39:20','2026-10-29 05:39:20'),(31,'stat_satisfaction_label','Statistik: Kepuasan Pelanggan (Label)','about','Kepuasan Pelanggan','2026-10-29 05:39:20','2026-10-29 05:39:20'),(32,'stat_legal_count','Statistik: Legalitas Resmi (Angka)','about','100+','2026-10-29 05:39:20','2026-10-29 06:52:16'),(33,'stat_legal_label','Statistik: Legalitas Resmi (Label)','about','Legalitas Resmi','2026-10-29 05:39:20','2026-10-29 05:39:20'),(34,'google_maps_embed_url','Google Maps Embed URL (Iframe)','general','https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d127118.81423406987!2d105.18788934440026!3d-5.419086111369344!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e40da4290c58e77%3A0xb696f5341cf60f4e!2sBandar%20Lampung%2C%20Kota%20Bandar%20Lampung%2C%20Lampung!5e0!3m2!1sid!2sid!4v1700000000000!5m2!1sid!2sid','2026-10-31 18:03:51','2026-10-31 18:03:51'),(35,'company_legal_name','Nama Badan Usaha','about','Nirwana Tour Travel','2026-11-03 02:39:21','2026-11-03 05:55:05'),(36,'about_story_title','Judul Cerita','about','Berawal dari Kecintaan Mendalam pada Pesona Bumi Ruwa Jurai','2026-11-03 02:39:21','2026-11-03 05:55:05'),(37,'company_vision','Visi Perusahaan','about','Menjadi biro perjalanan wisata terdepan, tepercaya, dan bereputasi prima di Lampung serta Indonesia, yang dikenal atas keunggulan layanan, integritas bisnis, standar keselamatan tinggi, dan kontribusi nyata dalam memajukan potensi pariwisata lokal yang berkelanjutan.','2026-11-03 02:39:21','2026-11-03 05:55:05'),(38,'hero_badge','Badge Hero','home','Biro Perjalanan Wisata Resmi Lampung','2026-11-03 03:11:07','2026-11-03 05:55:07'),(39,'hero_feature_1','Feature 1','home','Legalitas Berizin Resmi','2026-11-03 03:11:07','2026-11-03 05:55:07'),(40,'social_proof_headline','Social Proof','social_proof','Kepuasan 99% dari 500+ Rombongan','2026-11-03 03:11:07','2026-11-03 05:55:07');
