INSERT INTO `testimonials` VALUES (1,'Drs. Hendra Setiawan, M.Pd.','SMA Negeri 2 Bandar Lampung','Wakil Kepala Sekolah Bidang Kesiswaan',5,'Study tour 180 siswa kami ke Yogyakarta dan Bandung berjalan sangat rapi, tepat waktu, dan aman. Driver bus sangat sabar dan tour leader Nirwana Tour sigap melayani kebutuhan siswa dari awal penyeberangan hingga pulang.',NULL,'Study Tour Jogja-Bandung 2025',1,1,'2026-10-26 22:57:57','2026-10-26 22:57:57'),(2,'Ratna Dewi Kusuma','Divisi HRD Bank Mandiri Area Lampung','Ketua Panitia Gathering',5,'Family gathering tahunan karyawan di Pulau Pahawang sangat sukses! Games outbound-nya seru, makanan seafood-nya melimpah dan segar, serta dokumentasi drone dan foto underwater-nya keren banget. Recommended!',NULL,'Company Gathering Pahawang',1,2,'2026-10-26 22:57:57','2026-10-26 22:57:57'),(3,'Budi Prasetyo, S.T.','Ikatan Alumni Universitas Lampung','Ketua Rombongan',5,'Pelayanan sewa bus pariwisatanya istimewa. Kondisi armada Big Bus Jetbus sangat bersih, AC dingin, dan suspensi empuk untuk perjalanan jauh ke Bromo-Malang. Tidak ada kendala teknis sama sekali.',NULL,'Reuni & Trip Bromo Malang',1,3,'2026-10-26 22:57:57','2026-10-26 22:57:57'),(4,'Siti Nurhaliza & Keluarga','Wisatawan Asal Palembang','Family Trip',5,'Pertama kali bawa anak-anak ke Teluk Kiluan melihat lumba-lumba liar. Pelayanannya sangat ramah, homestay bersih dan pemandunya sangat teliti menjaga keselamatan kami di laut.',NULL,'Private Trip Teluk Kiluan',1,4,'2026-10-26 22:57:57','2026-10-26 22:57:57'),(5,'Ahmad Faisal','PT Mitra Sejahtera Lampung','Ketua Panitia Gathering',5,'Pelayanan sangat memuaskan, bus nyaman dan tour leadernya ramah sekali!',NULL,'Family Gathering Pahawang 2D1N',0,99,'2026-10-28 23:01:16','2026-10-28 23:01:16'),(6,'Ahmad Faisal','PT Mitra Sejahtera Lampung','Ketua Panitia Gathering',5,'Pelayanan sangat memuaskan, bus nyaman dan tour leadernya ramah sekali!',NULL,'Family Gathering Pahawang 2D1N',0,99,'2026-10-28 23:01:37','2026-10-28 23:01:37'),(7,